import json
def f(i):
    H,W=len(i),len(i[0])
    o=[row[:] for row in i]
    bg=max(set(x for r in i for x in r),key=lambda v:sum(r.count(v) for r in i))
    # connected components of non-bg? treat all colored cells as markers
    comps=[]
    seen=set()
    import collections
    for r in range(H):
        for c in range(W):
            if i[r][c]!=bg and (r,c) not in seen:
                stack=[(r,c)]; comp=set([(r,c)])
                while stack:
                    a,b=stack.pop()
                    for dr in(-1,0,1):
                        for dc in(-1,0,1):
                            x,y=a+dr,b+dc
                            if 0<=x<H and 0<=y<W and i[x][y]!=bg and (x,y) not in comp:
                                comp.add((x,y)); stack.append((x,y))
                comps.append(comp)
    for comp in comps:
        if len(comp)>=2:
            rs=[a for a,b in comp]; cs=[b for a,b in comp]
            r0,r1=min(rs),max(rs); c0,c1=min(cs),max(cs)
            for c in range(c0,c1+1):
                for rr in (r0,r1):
                    o[rr][c]=2 if o[rr][c]==bg else o[rr][c]
                    if o[rr][c]!=i[rr][c]: o[rr][c]=2
            for r in range(r0,r1+1):
                for cc in (c0,c1):
                    if o[r][cc]==bg: o[r][cc]=2
    return o
