    bg=Ct(x for r in g for x in r).most_common(1)[0][0]
    mk=[(r,c) for r in range(H) for c in range(W) if g[r][c]!=bg]
    o=[row[:] for row in g]
    def mark(r,c):
        if g[r][c]==bg: o[r][c]=2
    r0=min(r for r,c in mk); r1=max(r for r,c in mk); c0=min(c for r,c in mk); c1=max(c for r,c in mk)
    for name,(r_,f) in [('top',(r0,range(W))),('bot',(r1,range(W))),('left',(None,range(H),c0)),('right',(None,range(H),c1))]:
        pts=[(rr,c) for rr in (range(H) if name in('left','right') else [r_]) for c in f if g[rr][c]!=bg] if name in('left','right') else [(r_,c) for c in f if g[r_][c]!=bg]
        cs=sorted(p[1] for p in pts) if name in('top','bot') else sorted(p[0] for p in pts)
        if len(cs)<=1:
            rng=range(r0,r1+1) if name in('left','right') else range(c0,c1+1)
            ax = 0 if name in('left','right') else 1
            for t in rng:
                mark(t if name in('left','right') else None,t)
        else:
            for a,b in zip(cs,cs[1:]):
                if b-a>=2:
                    if name in('top','bot'):
                        for c in range(a+1,b): mark(r_,c)
                    else:
                        for t in range(a+1,b): mark(t,c_)
    return o
